input.newString:
export default function Home() {
  // Log page view without blocking the response
  logPageView();

  return (
    <main>
      <h1>Welcome</h1>
      <p>Page view logged successfully!</p>
    </main>
  );
}

// Analytics service simulation
async function logPageView() {
  // Using Next.js's approach to schedule work after response
  // This ensures the logging doesn't block the page rendering
  setTimeout(() => {
    console.log('Page view logged to analytics service');
    // In a real implementation, this would call an actual analytics service
    // fetch('/api/analytics', { method: 'POST', body: JSON.stringify({ page: 'home' }) });
  }, 0);
}

